        {var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-frontier-industrial-audit");if(i<0||i+1>=args.Length)return;var audit=new GameObject("Prueba de industria y misiles").AddComponent<IndustrialPresentationAudit>();audit.folder=Path.GetFullPath(args[i+1]);Directory.CreateDirectory(audit.folder);}
        private void OnEnable()=>Application.logMessageReceived+=Log;
