        private IEnumerator Run()
        {
            yield return null;var p=FindAnyObjectByType<FrontierPrototype>();p.AuditManualSimulation=true;p.Settings.ReducedMotion=false;p.PlayerName="Horizonte Atlántico";p.BeginLocationSelection();var g=p.Simulation;g.AiEnabled=false;g.ReinforcementsEnabled=false;g.Rules.victoryFraction=1;
            Check(p.World.Width==3110&&p.World.Height==1555,"Tierra completa con dimensiones reducidas 28%");int nation=Array.FindIndex(p.World.Countries,c=>c.code=="PRT"),center=p.World.StartCells[nation];int start=Enumerable.Range(10,60).Select(n=>center+n).First(c=>g.CanFoundAt(c));p.SelectFoundation(start);Check(p.ConfirmFoundation()&&g.Troops[g.PlayerFaction]==10000,"Fundación libre con 10.000 tropas");int f=g.PlayerFaction,x=start%p.World.Width,y=start/p.World.Width;
