            Func<BuildingKind,Vector2,int> place=(kind,position)=>g.OwnedCells(f).Where(c=>g.ValidateConstruction(f,c,kind).success).OrderBy(c=>Vector2.Distance(new Vector2(c%p.World.Width,c/p.World.Width),position)).First();
            int city=place(BuildingKind.City,new Vector2(x-12,y+8));Check(g.Construct(f,city,BuildingKind.City).success,"Ciudad original");int factory=place(BuildingKind.Factory,new Vector2(x+16,y+8));Check(g.Construct(f,factory,BuildingKind.Factory).success,"Fábrica original");int port=place(BuildingKind.Port,new Vector2(x-30,y));Check(g.Construct(f,port,BuildingKind.Port).success,"Puerto conectado por tierra");int silo1=place(BuildingKind.Silo,new Vector2(x-10,y-10));g.Construct(f,silo1,BuildingKind.Silo);int silo2=place(BuildingKind.Silo,new Vector2(x+10,y-10));g.Construct(f,silo2,BuildingKind.Silo);
            for(int i=0;i<250;i++){g.Step(.1f);yield return null;}Check(g.Ledgers[f].landTrade>0&&g.Trains.Count>0,"Flota lógica entrega oro en ciudad, fábrica y puerto");camera.Focus(new Vector2(x,y),180);p.OpenCampaignPanel(CampaignPanel.Information,factory);yield return new WaitForSecondsRealtime(.5f);Capture("01_fabrica_alcance_e_ingresos");yield return null;p.CloseCampaignPanel();camera.Focus(new Vector2(x,y),42);yield return new WaitForSecondsRealtime(.3f);
            var models=p.Visuals.GetComponent<StrategicMissileVisuals>();yield return null;Check(models.VisibleSilos==2,"Las dos bases de lanzamiento originales aparecen en el mapa");Capture("02_silos_y_conexiones");yield return null;
            int preview=place(BuildingKind.Factory,new Vector2(x+30,y-20));p.OpenCampaignPanel(CampaignPanel.Construction,preview);p.SelectedBuilding=BuildingKind.Factory;for(int i=0;i<50;i++){g.Step(.1f);yield return null;}Capture("03_previsualizacion_de_conexiones");yield return null;p.CloseCampaignPanel();
            int enemy=Array.FindIndex(p.World.Countries,c=>c.code=="FRA"),target=g.CapitalCells[enemy];Claim(g,enemy,target,22);g.RebuildCampaignIndexes();g.Gold[enemy]=10000000;foreach(int n in Enumerable.Range(0,g.FactionCount))g.ProtectionUntil[n]=0;
            int defense=g.OwnedCells(enemy).Where(c=>g.ValidateConstruction(enemy,c,BuildingKind.SAM).success).OrderBy(c=>Vector2.Distance(new Vector2(c%p.World.Width,c/p.World.Width),new Vector2(target%p.World.Width+7,target/p.World.Width))).First();g.Construct(enemy,defense,BuildingKind.SAM);for(int i=0;i<50;i++){g.Step(.1f);yield return null;}
            p.OpenCampaignPanel(CampaignPanel.Information,defense);camera.Focus(new Vector2(defense%p.World.Width,defense/p.World.Width),120);yield return new WaitForSecondsRealtime(.3f);Capture("04_sam_cobertura_y_recarga");yield return null;p.CloseCampaignPanel();
