            g.DestroyBuilding(g.BuildingAt(defense),f);Check(g.LaunchWeapon(f,target,WeaponKind.Hydrogen).success,"Cohete pesado desde el silo");p.AuditManualSimulation=false;yield return new WaitForSecondsRealtime(.8f);var flying=g.Projectiles.First(q=>q.active);var flight=g.ProjectilePosition(flying);camera.Focus(new Vector2(flight.x,flight.z+flight.y/Mathf.Tan(78*Mathf.Deg2Rad)),30);yield return new WaitForSecondsRealtime(.25f);Check(models.VisibleMissiles>0&&models.SmokeParticles>0&&models.SmokeParticles<=StrategicMissileVisuals.MaximumMissiles*StrategicMissileVisuals.MaximumSmokePerMissile,"Estela de partículas visible y acotada");Capture("07_cohete_pesado_estela");yield return new WaitForSecondsRealtime(.4f);Capture("07b_humo_en_movimiento");yield return new WaitForSecondsRealtime(9);p.AuditManualSimulation=true;Check(g.Radiation.Count>0,"Explosión deja zona nuclear persistente");camera.Focus(new Vector2(target%p.World.Width,target/p.World.Width),115);Capture("08_huella_nuclear_verde");yield return null;
            typeof(MapVisuals).GetMethod("OnStrategicCell",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(p.Visuals,new object[]{p.World.Land.Length-1});yield return null;yield return null;Check(errors==0,"Actualización del último bloque parcial del mapa sin errores");
            var structures=p.Visuals.GetComponent<StructureModelVisuals>();Matrix4x4? baseline=null;foreach(float zoom in new[]{42f,88f,92f,238f,242f})
            {camera.Focus(new Vector2(city%p.World.Width,city/p.World.Width),zoom);yield return new WaitForSecondsRealtime(.2f);var matrices=(Matrix4x4[][])typeof(StructureModelVisuals).GetField("_matrices",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(structures);var current=matrices[1][0];if(baseline.HasValue)Check(current==baseline.Value,"Estructura sin saltos de escala a zoom "+zoom);else baseline=current;Capture("zoom_"+zoom);yield return null;}
            for(int n=0;n<p.World.Countries.Length;n++)if(g.TerritoryCounts[n]>0&&g.CapitalCells[n]>=0)Claim(g,n,g.CapitalCells[n],18);g.RebuildCampaignIndexes();
            for(int n=0;n<p.World.Countries.Length;n++)if(g.TerritoryCounts[n]>0)
            {g.Gold[n]=2000000;int c=g.OwnedCells(n).Where(id=>g.ValidateConstruction(n,id,BuildingKind.City).success).DefaultIfEmpty(-1).First();if(c>=0)g.Construct(n,c,BuildingKind.City);int origin=c;int b=g.OwnedCells(n).Where(id=>g.ValidateConstruction(n,id,BuildingKind.Factory).success&&(origin<0||Vector2.Distance(new Vector2(id%p.World.Width,id/p.World.Width),new Vector2(origin%p.World.Width,origin/p.World.Width))>=GMin(g))).DefaultIfEmpty(-1).First();if(b>=0)g.Construct(n,b,BuildingKind.Factory);}
            for(int i=0;i<100;i++){g.Step(.1f);yield return null;}camera.ResetView();yield return new WaitForSecondsRealtime(.4f);Capture("09_mundo_compacto");yield return null;Check(structures.VisibleModels>250,"Cientos de ciudades y fábricas instanciadas visibles");
            g.AiEnabled=true;g.ReinforcementsEnabled=true;g.MeasurePerformance=true;p.AuditManualSimulation=false;var all=new List<float>();var late=new List<float>();var args=Environment.GetCommandLineArgs();int durationIndex=Array.IndexOf(args,"-frontier-audit-seconds");float duration=durationIndex>=0&&durationIndex+1<args.Length&&float.TryParse(args[durationIndex+1],out float requested)?Mathf.Clamp(requested,30,300):300;float began=Time.realtimeSinceStartup,next=30;int peakTrains=g.Trains.Count,peakModels=structures.VisibleModels;
            while(Time.realtimeSinceStartup-began<duration){float elapsed=Time.realtimeSinceStartup-began;all.Add(Time.unscaledDeltaTime*1000);if(elapsed>=Mathf.Min(180,duration*.6f))late.Add(Time.unscaledDeltaTime*1000);peakTrains=Mathf.Max(peakTrains,g.Trains.Count);peakModels=Mathf.Max(peakModels,structures.VisibleModels);if(elapsed>=next){Debug.Log("INDUSTRIAL_SOAK seconds="+elapsed+" buildings="+g.Buildings.Count+" trains="+g.Trains.Count+" missiles="+g.Projectiles.Count);next+=30;}yield return null;}
            all.Sort();late.Sort();Check(errors==0,"Recorrido de "+duration+" segundos sin errores");File.WriteAllText(Path.Combine(folder,"industrial-native.json"),JsonUtility.ToJson(new Report{inEditor=Application.isEditor,errors=errors,width=p.World.Width,height=p.World.Height,checks=checks.ToArray(),seconds=(int)duration,peakTrains=peakTrains,peakModels=peakModels,drawCalls=structures.DrawCalls,fps=all.Count*1000/all.Sum(),p95Ms=all[(int)(all.Count*.95f)],maximumMs=all.Last(),fpsAfterThreeMinutes=late.Count*1000/late.Sum(),p95AfterThreeMinutes=late[(int)(late.Count*.95f)]},true));Debug.Log("INDUSTRIAL_NATIVE_COMPLETE");
        }
        private static float GMin(TerritorySimulation g)=>g.Rules.factoryConnectionMinimum*g.World.ResolutionScale;
